"""Sequential fault scenario sets for the modified IEEE 123-node system.

The records are exported from ``DOKSURI_sequential_scenario_sets.xlsx``.
Each scenario preserves the three during-event fault stages (t=2, t=3,
and t=4), as well as each line's repair completion stage.  A fault listed
at an earlier stage remains unavailable until its recorded repair stage.
The flat ``faulted_lines`` field is retained for compatibility with the
simpler scenario format used in the reference GitHub file.
"""
